INSERT INTO INT_SERVERFUNCTION (ID, NAME, DESCRIPTION, TYPE, CODE, JDBC_ID, PUBLIC_EXECUTION, CRON_EXPRESSION, CRON_INPUT_JSON, CREATED_BY) VALUES (134, 'hotColabRefs', 'Refs de Colaboradores em 1 ida (CRS,EMPRESAS,CARGOS). Sem params.', 'SQL', 'SELECT COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT(''ID'',t.ID,''CODIGO'',t.CODIGO,''NOME'',t.NOME,''EMPRESA_ID'',t.EMPRESA_ID,''ATIVO'',t.ATIVO)) FROM CENTRO_RESULTADO t WHERE t.ATIVO = ''true''),JSON_ARRAY()) AS CRS, COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT(''ID'',t.ID,''NOME'',t.NOME,''CNPJ'',t.CNPJ,''ATIVO'',t.ATIVO,''CRIADO_EM'',t.CRIADO_EM)) FROM EMPRESA t WHERE 1=1),JSON_ARRAY()) AS EMPRESAS, COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT(''ID'',t.ID,''NOME'',t.NOME,''SALARIO_MEDIO'',t.SALARIO_MEDIO,''ATIVO'',t.ATIVO)) FROM CARGO t WHERE t.ATIVO = ''true''),JSON_ARRAY()) AS CARGOS', NULL, FALSE, NULL, NULL, 'sarah@mitralab.io');
